#!/usr/bin/env bash
# Android module driver (docs/CONVENTIONS.md section 7).
#
#   bench_android.sh prepare|build|install|run|size|clean [options]
#   options: --version V --source maven|local --variant plain|sdk|sentinel --scenario default|largeapk|diag
#            --out DIR --serial SERIAL --iterations N --round R --position P --metric-set init|micro|macro
#            --with-tests (build also assembles the micro/macro test APKs) --crash native|java (init lane)
#            --env env.json --run-id ID --fixture DIR (largeapk asset fixture; generated by prepare)
#   run --metric-set init   : N cold starts via `am start -W`, pulls the app's bench-result.json after each launch
#   run --metric-set micro  : connectedReleaseAndroidTest of :microbenchmark (benchmarkData.json + bench-result-micro.json)
#   run --metric-set macro  : connectedBenchmarkAndroidTest of :macrobenchmark against the installed app identity
#   size                    : A3 rows (APK, per-ABI .so, DEX refs, bundletool install size per device spec)
# Exit 4 = unsupported cell (SDK version not resolvable). Never contacts a production endpoint.
set -euo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
android_dir="$(cd "$here/.." && pwd)"
repo="$(cd "$android_dir/.." && pwd)"
BUNDLETOOL_VERSION="1.18.3"
BUNDLETOOL_SHA256="a099cfa1543f55593bc2ed16a70a7c67fe54b1747bb7301f37fdfd6d91028e29"
sdk_root="${ANDROID_HOME:-${ANDROID_SDK_ROOT:-$HOME/Library/Android/sdk}}"

cmd="${1:-}"; shift || true
version="3.14.0" source="maven" variant="sdk" scenario="default" out="" serial="${ANDROID_SERIAL:-}" iterations=15
round=0 position=0 metric_set="init" with_tests=0 crash="" env_json="" run_id="local" fixture="" local_path=""
while [ $# -gt 0 ]; do
  case "$1" in
    --version) version="$2"; shift 2;; --source) source="$2"; shift 2;; --variant) variant="$2"; shift 2;;
    --scenario) scenario="$2"; shift 2;; --out) out="$2"; shift 2;; --serial) serial="$2"; shift 2;;
    --iterations) iterations="$2"; shift 2;; --round) round="$2"; shift 2;; --position) position="$2"; shift 2;;
    --metric-set) metric_set="$2"; shift 2;; --with-tests) with_tests=1; shift;; --crash) crash="$2"; shift 2;;
    --env) env_json="$2"; shift 2;; --run-id) run_id="$2"; shift 2;; --fixture) fixture="$2"; shift 2;;
    --local-path) local_path="$2"; shift 2;; --device|--udid) serial="$2"; shift 2;;
    *) echo "bench_android.sh: unknown argument $1" >&2; exit 1;;
  esac
done
version_id="v$(echo "$version" | tr '.-' '__')"
module="app-sdk"; [ "$variant" = "plain" ] && module="app-plain"
app_id="io.backtrace.bench.$variant.$version_id"
activity="io.backtrace.bench.app.MainActivity"
[ "$scenario" = "largeapk" ] && [ -z "$fixture" ] && fixture="$android_dir/build/fixture"
props=(-PbtVersion="$version" -PbtVariant="$variant" -PbtScenario="$scenario" -PbtSource="$source")
[ "$scenario" = "largeapk" ] && props+=(-PbtFixtureAssets="$fixture")
gradle() { (cd "$android_dir" && ./gradlew ${BT_GRADLE_ARGS:---no-daemon -q} "$@"); }
adb() { if [ -n "$serial" ]; then "$sdk_root/platform-tools/adb" -s "$serial" "$@"; else "$sdk_root/platform-tools/adb" "$@"; fi; }
# Gradle writes every cell to the same output path, so build copies its products into a per-cell directory and
# install/run/size only ever read from there (a later build for another version cannot swap the APK underneath).
cell_dir="$android_dir/build/cells/$app_id-$scenario"
gradle_apk() { echo "$android_dir/$module/build/outputs/apk/release/$module-release.apk"; }
gradle_aab() { echo "$android_dir/$module/build/outputs/bundle/release/$module-release.aab"; }
apk_path() { echo "$cell_dir/app.apk"; }
aab_path() { echo "$cell_dir/app.aab"; }
micro_apk() { echo "$cell_dir/microbenchmark-androidTest.apk"; }
macro_apk() { echo "$cell_dir/macrobenchmark.apk"; }
log() { echo "bench_android.sh[$variant $version $scenario]: $*"; }

gradle_or_unsupported() {  # gradle_or_unsupported <logfile> <tasks...>
  local logf="$1"; shift
  set +e; gradle "$@" >"$logf" 2>&1; local rc=$?; set -e
  if [ $rc -ne 0 ]; then
    if grep -q -E "Could not find com.github.backtrace-labs|Could not resolve com.github.backtrace-labs" "$logf"; then
      log "SDK version $version is not resolvable from $source"; tail -5 "$logf" >&2; return 4
    fi
    tail -40 "$logf" >&2; return 1
  fi
}

case "$cmd" in
  prepare)
    if [ "$scenario" = "largeapk" ]; then python3 "$here/gen_fixture.py" --entries 10000 --out "$fixture"; fi
    if [ "$source" = "local" ] && [ -n "$local_path" ]; then
      OUT_DIR="${out:-$repo/out}" "$repo/scripts/ci/publish_android_local.sh" "$local_path"
      log "published local SDK: $(cat "${out:-$repo/out}/local-version.txt")"
    fi
    log "prepared"
    ;;
  build)
    mkdir -p "${out:-$android_dir/build}/logs"
    tasks=(":$module:assembleRelease")
    if [ $with_tests -eq 1 ] && [ "$variant" != "plain" ]; then tasks+=(":microbenchmark:assembleReleaseAndroidTest" ":macrobenchmark:assembleBenchmark"); fi
    log "building ${tasks[*]}"
    gradle_or_unsupported "${out:-$android_dir/build}/logs/build-$variant-$version_id.log" "${tasks[@]}" "${props[@]}"
    mkdir -p "$cell_dir"; cp "$(gradle_apk)" "$(apk_path)"
    if [ $with_tests -eq 1 ] && [ "$variant" != "plain" ]; then
      cp "$android_dir/microbenchmark/build/outputs/apk/androidTest/release/microbenchmark-release-androidTest.apk" "$(micro_apk)"
      cp "$android_dir/macrobenchmark/build/outputs/apk/benchmark/macrobenchmark-benchmark.apk" "$(macro_apk)"
    fi
    if [ -n "$out" ]; then mkdir -p "$out/apk"; cp "$(apk_path)" "$out/apk/$app_id.apk"; fi
    log "built $(apk_path) ($(stat -f%z "$(apk_path)" 2>/dev/null || stat -c%s "$(apk_path)") bytes) appId=$app_id"
    ;;
  install)
    [ -f "$(apk_path)" ] || { log "no built APK for this cell; run build first"; exit 1; }
    adb install -r -g "$(apk_path)" >/dev/null
    if [ $with_tests -eq 1 ] && [ "$variant" != "plain" ]; then
      [ -f "$(micro_apk)" ] && adb install -r -t "$(micro_apk)" >/dev/null
      [ -f "$(macro_apk)" ] && adb install -r -t "$(macro_apk)" >/dev/null
    fi
    log "installed $app_id"
    ;;
  run)
    [ -n "$out" ] || { echo "run needs --out" >&2; exit 1; }
    mkdir -p "$out"
    case "$metric_set" in
      init)
        media="/sdcard/Android/media/$app_id/bench-result.json"
        extras=(); [ "$crash" = "native" ] && extras=(--ez crash_native true); [ "$crash" = "java" ] && extras=(--ez crash_java true)
        adb shell settings put global window_animation_scale 0 >/dev/null 2>&1 || true
        adb shell settings put global transition_animation_scale 0 >/dev/null 2>&1 || true
        adb shell settings put global animator_duration_scale 0 >/dev/null 2>&1 || true
        adb logcat -c || true
        ok=0
        for i in $(seq 1 "$iterations"); do
          adb shell am force-stop "$app_id"; adb shell "rm -f $media" >/dev/null 2>&1 || true
          sleep 1
          adb shell am start -W -n "$app_id/$activity" ${extras[@]+"${extras[@]}"} > "$out/am-start-$i.txt" 2>&1 || true
          got=0
          for _ in $(seq 1 40); do
            if adb shell "cat $media" > "$out/bench-result-$i.json" 2>/dev/null && python3 -c "import json,sys; json.load(open(sys.argv[1]))" "$out/bench-result-$i.json" 2>/dev/null; then got=1; break; fi
            sleep 0.5
          done
          if [ $got -eq 1 ]; then ok=$((ok+1)); else rm -f "$out/bench-result-$i.json"; log "launch $i: no bench-result (see am-start-$i.txt)"; fi
        done
        adb logcat -d -s BacktraceBench:I BacktraceBenchData:I > "$out/logcat.txt" 2>/dev/null || true
        adb shell am force-stop "$app_id" || true
        log "init lane: $ok/$iterations launches produced bench-result.json"
        [ $ok -gt 0 ] || exit 1
        ;;
      micro)
        [ "$variant" != "plain" ] || { log "micro lane needs the sdk variant"; exit 1; }
        export ANDROID_SERIAL="${serial:-${ANDROID_SERIAL:-}}"
        gradle_or_unsupported "$out/gradle-micro.log" ":microbenchmark:connectedReleaseAndroidTest" "${props[@]}" "-Pandroid.testInstrumentationRunnerArguments.androidx.benchmark.profiling.mode=None"
        find "$android_dir/microbenchmark/build/outputs" -name '*benchmarkData*.json' -exec cp {} "$out/" \;
        find "$android_dir/microbenchmark/build/outputs" -name 'bench-result-micro.json' -exec cp {} "$out/" \;
        if [ ! -s "$out/bench-result-micro.json" ]; then
          adb shell "cat /sdcard/Android/media/io.backtrace.bench.micro.test/bench-result-micro.json" > "$out/bench-result-micro.json" 2>/dev/null || true
          [ -s "$out/bench-result-micro.json" ] || rm -f "$out/bench-result-micro.json"
        fi
        log "micro lane: $(ls "$out"/*benchmarkData*.json 2>/dev/null | wc -l | tr -d ' ') benchmarkData file(s)"
        ;;
      macro)
        export ANDROID_SERIAL="${serial:-${ANDROID_SERIAL:-}}"
        gradle_or_unsupported "$out/gradle-macro.log" ":macrobenchmark:connectedBenchmarkAndroidTest" "${props[@]}" \
          "-Pandroid.testInstrumentationRunnerArguments.bt.package=$app_id" "-Pandroid.testInstrumentationRunnerArguments.bt.iterations=$iterations" "-Pandroid.testInstrumentationRunnerArguments.androidx.benchmark.profiling.mode=None"
        find "$android_dir/macrobenchmark/build/outputs" -name '*benchmarkData*.json' -exec cp {} "$out/" \;
        adb logcat -d -s BacktraceBenchData:I > "$out/logcat-macro.txt" 2>/dev/null || true
        log "macro lane: $(ls "$out"/*benchmarkData*.json 2>/dev/null | wc -l | tr -d ' ') benchmarkData file(s)"
        ;;
      *) echo "unknown --metric-set $metric_set" >&2; exit 1;;
    esac
    ;;
  size)
    [ -n "$out" ] || { echo "size needs --out" >&2; exit 1; }
    mkdir -p "$out" "$repo/artifacts/tools"
    jar="$repo/artifacts/tools/bundletool-all-$BUNDLETOOL_VERSION.jar"
    if [ ! -f "$jar" ]; then
      curl -fsSL --retry 3 -o "$jar" "https://github.com/google/bundletool/releases/download/$BUNDLETOOL_VERSION/bundletool-all-$BUNDLETOOL_VERSION.jar"
    fi
    echo "$BUNDLETOOL_SHA256  $jar" | shasum -a 256 -c - >/dev/null || { echo "bundletool checksum mismatch" >&2; exit 1; }
    mkdir -p "$cell_dir"
    if [ ! -f "$(apk_path)" ]; then gradle_or_unsupported "$out/gradle-size-build.log" ":$module:assembleRelease" "${props[@]}"; cp "$(gradle_apk)" "$(apk_path)"; fi
    gradle_or_unsupported "$out/gradle-size-bundle.log" ":$module:bundleRelease" "${props[@]}"; cp "$(gradle_aab)" "$(aab_path)"
    apkanalyzer=""
    for c in "$sdk_root/cmdline-tools/latest/bin/apkanalyzer" "$sdk_root/tools/bin/apkanalyzer"; do [ -x "$c" ] && { apkanalyzer="$c"; break; }; done
    args=(--apk "$(apk_path)" --aab "$(aab_path)" --bundletool "$jar" --sdk-version "$version" --variant "$variant" --source "$source" --scenario "$scenario" --run-id "$run_id" --out "$out/rows-size-$variant.jsonl")
    [ -n "$apkanalyzer" ] && args+=(--apkanalyzer "$apkanalyzer")
    [ -n "$env_json" ] && args+=(--env "$env_json")
    python3 "$here/size_rows.py" "${args[@]}"
    ;;
  clean)
    gradle clean "${props[@]}" >/dev/null 2>&1 || true; rm -rf "$android_dir/build/fixture" "$android_dir/build/cells"; log "cleaned"
    ;;
  *) echo "usage: bench_android.sh prepare|build|install|run|size|clean [options]" >&2; exit 1;;
esac
